import {_electron} from '/tmp/framework-platforms-20260909/node-tools/node_modules/playwright/index.mjs'
import electronPath from 'electron'
import {readFileSync} from 'node:fs'
const app=await _electron.launch({executablePath:electronPath,args:['.','--disable-setuid-sandbox'],chromiumSandbox:true,timeout:30000})
try {
 const page=await app.firstWindow();await page.waitForLoadState('domcontentloaded')
 const state=await app.evaluate(({BrowserWindow})=>{const w=BrowserWindow.getAllWindows()[0];return {argv:process.argv,prefs:w.webContents.getLastWebPreferences(),rendererPID:w.webContents.getOSProcessId()}})
 const status=readFileSync(`/proc/${state.rendererPID}/status`,'utf8').split('\n').filter(x=>/^(Name|NoNewPrivs|Seccomp|NSpid):/.test(x))
 console.log(JSON.stringify({title:await page.title(),state,status},null,2))
 if(state.argv.includes('--no-sandbox')||state.prefs.sandbox!==true)throw Error('Sandbox preflight failed')
} finally {await app.close()}
